import { mkdir, writeFile } from 'node:fs/promises';
import { score } from './lib/score.mjs';

const scale = Number.parseInt(process.env.SCORE_SCALE ?? '1', 10);
const prefix = process.env.REPORT_PREFIX ?? 'local';
const rows = [
  { name: 'beta', score: score(2, scale) },
  { name: 'alpha', score: score(4, scale) },
];
await mkdir('out', { recursive: true });
await writeFile('out/report.json', JSON.stringify({ prefix, rows }, null, 2) + '\n');

