import json


def render(payload):
    rows = sorted(payload["rows"], key=lambda row: row["name"], reverse=True)
    return "\n".join(
        f'{payload["prefix"]}:{row["name"]}={row["score"]}' for row in rows
    )


if __name__ == "__main__":
    with open("out/report.json", encoding="utf-8") as handle:
        print(render(json.load(handle)))
